#!/usr/bin/env python3
# Restore case-sensitive files lost on Windows (12 netfilter files)
import base64, os
FILES = {
 "include/uapi/linux/netfilter/xt_connmark.h": "",
 "include/uapi/linux/netfilter/xt_dscp.h": "",
 "include/uapi/linux/netfilter/xt_mark.h": "I2lmbmRlZiBfWFRfTUFSS19ICiNkZWZpbmUgX1hUX01BUktfSAoKI2luY2x1ZGUgPGxpbnV4L3R5cGVzLmg+CgpzdHJ1Y3QgeHRfbWFya190Z2luZm8yIHsKCV9fdTMyIG1hcmssIG1hc2s7Cn07CgpzdHJ1Y3QgeHRfbWFya19tdGluZm8xIHsKCV9fdTMyIG1hcmssIG1hc2s7CglfX3U4IGludmVydDsKfTsKCiNlbmRpZiAvKl9YVF9NQVJLX0gqLwo=",
 "include/uapi/linux/netfilter/xt_rateest.h": "",
 "include/uapi/linux/netfilter/xt_tcpmss.h": "I2lmbmRlZiBfWFRfVENQTVNTX01BVENIX0gKI2RlZmluZSBfWFRfVENQTVNTX01BVENIX0gKCiNpbmNsdWRlIDxsaW51eC90eXBlcy5oPgoKc3RydWN0IHh0X3RjcG1zc19tYXRjaF9pbmZvIHsKICAgIF9fdTE2IG1zc19taW4sIG1zc19tYXg7CiAgICBfX3U4IGludmVydDsKfTsKCiNlbmRpZiAvKl9YVF9UQ1BNU1NfTUFUQ0hfSCovCg==",
 "include/uapi/linux/netfilter_ipv4/ipt_ecn.h": "",
 "include/uapi/linux/netfilter_ipv4/ipt_ttl.h": "",
 "include/uapi/linux/netfilter_ipv6/ip6t_hl.h": "",
 "net/netfilter/xt_dscp.c": "",
 "net/netfilter/xt_hl.c": "",
 "net/netfilter/xt_rateest.c": "",
 "net/netfilter/xt_tcpmss.c": ""
}
for rel, b64 in FILES.items():
    os.makedirs(os.path.dirname(rel), exist_ok=True)
    with open(rel, 'wb') as f:
        f.write(base64.b64decode(b64))
    print('restored:', rel)
